// Generates src/kit/index.js — the family loaders — from the family folders.
//
//   node tools/kit_index.mjs            write src/kit/index.js
//   node tools/kit_index.mjs --check    exit 1 when the file is out of date
//
// A family is a folder src/kit/<family>/ with an index.js that exports
// `assets` (an array of defineAsset records). The generated file is a map of
// dynamic imports, carrying the cache tag from src/main.js, so classic mode
// downloads nothing and modular mode fetches one small module per family.
// Never hand-edit src/kit/index.js: the Integrator runs this at every merge
// and tools/kit_check.mjs fails when it drifts.
import { existsSync, readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

export const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
export const KIT_DIR = join(ROOT, 'src', 'kit');
export const INDEX_FILE = join(KIT_DIR, 'index.js');

const strip = (s) => (s.charCodeAt(0) === 0xFEFF ? s.slice(1) : s);

/** The cache tag every module import carries (read from src/main.js). */
export function currentTag(root = ROOT) {
  const main = strip(readFileSync(join(root, 'src', 'main.js'), 'utf8'));
  const tag = (main.match(/\?v=([0-9a-z]+)/) || [])[1];
  if (!tag) throw new Error('no ?v= cache tag found in src/main.js');
  return tag;
}

/** Family folder names: every src/kit/<name>/ that holds an index.js, sorted. */
export function familyFolders(kitDir = KIT_DIR) {
  if (!existsSync(kitDir)) return [];
  return readdirSync(kitDir)
    .filter((name) => /^[a-z][a-z0-9-]*$/.test(name) && statSync(join(kitDir, name)).isDirectory())
    .filter((name) => existsSync(join(kitDir, name, 'index.js')))
    .sort();
}

/** The text of src/kit/index.js for the given families and tag. */
export function renderIndex(families, tag) {
  const lines = [
    '// GENERATED by tools/kit_index.mjs — do not edit by hand.',
    '// One loader per kit family (src/kit/<family>/index.js exports `assets`).',
    '// AssetRuntime.preload() imports these only when the modular set can be',
    '// active, so the classic game never downloads the kit.',
    `export const KIT_TAG = '${tag}';`,
    `export const FAMILY_NAMES = Object.freeze([${families.map((f) => `'${f}'`).join(', ')}]);`,
    'export const FAMILIES = Object.freeze({'
  ];
  for (const f of families) lines.push(`  '${f}': () => import('./${f}/index.js?v=${tag}'),`);
  lines.push('});', '');
  return lines.join('\n');
}

export function generateIndex(root = ROOT) {
  const kitDir = join(root, 'src', 'kit');
  const families = familyFolders(kitDir);
  const tag = currentTag(root);
  return { families, tag, text: renderIndex(families, tag), file: join(kitDir, 'index.js') };
}

/** True when src/kit/index.js matches what would be generated now. */
export function indexInSync(root = ROOT) {
  const { text, file } = generateIndex(root);
  return existsSync(file) && readFileSync(file, 'utf8') === text;
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const check = process.argv.includes('--check');
  const { families, tag, text, file } = generateIndex();
  const current = existsSync(file) ? readFileSync(file, 'utf8') : null;
  if (check) {
    if (current === text) { console.log(`OK   src/kit/index.js in sync (${families.length} families, tag ${tag})`); process.exit(0); }
    console.log('FAIL src/kit/index.js is out of date — run: node tools/kit_index.mjs');
    process.exit(1);
  }
  if (current === text) console.log(`unchanged src/kit/index.js (${families.length} families, tag ${tag})`);
  else { writeFileSync(file, text); console.log(`wrote src/kit/index.js (${families.length} families: ${families.join(', ') || 'none'}, tag ${tag})`); }
}
